using System;
using System.Collections.Generic;
namespace ElymsPet {
 static class NodeReadingGuideTests {
  static void Check(bool ok,string name){if(!ok)throw new Exception("Term guide: "+name);Console.WriteLine("PASS term guide: "+name);}
  public static void Run(string root){string url="https://github.com/org/repo/blob/"+new string('a',40)+"/file.py#L10";string evidence="来源："+url+"\n已读取并核对文件内容\nL10: one\nL11: two\nL12: three";var locations=new List<string>{url};Check(NodeReadingGuide.IsReadLocation(url.Replace("#L10","#L11-L12"),evidence,locations)&&!NodeReadingGuide.IsReadLocation(url.Replace("#L10","#L12-L14"),evidence,locations),"step links may target exact verified lines but cannot extend beyond the excerpt");using(var h=new GraphAiCreationTests.Harness(true,root)){
   var graph=h.Graph;var node=graph.Nodes.Find(n=>n.Id=="worker-npu");string original=GraphEditing.Json(node),edges=GraphEditing.Json(graph.Edges);var guide=new NodeReadingGuide{Terms=new List<GuideTerm>{new GuideTerm{Term="NPUWorker",Meaning="管理设备并接收模型执行请求的组件。"}},Steps=new List<GuideStep>{new GuideStep{Original=node.Summary,Explanation="测试未读取实现，对应源码尚未定位。"}}};h.Api.Result=GraphEditing.Json(guide);GraphEditOutcome result=null;
   h.Service.TranslateNodeTerms(graph,node,r=>result=r);h.Queue.Run();var saved=h.Graph.Nodes.Find(n=>n.Id==node.Id);var translation=saved.ReadingGuide;Check(result.Success&&h.Api.Calls==2&&translation.SourceRevision==NodeReadingGuide.Revision(saved),"translation uses draft and review and records the original revision");saved.ReadingGuide=null;Check(GraphEditing.Json(saved)==original&&GraphEditing.Json(h.Graph.Edges)==edges,"translation never rewrites description, code, learning notes or graph relationships");saved.ReadingGuide=translation;
   var roundTrip=DomainKnowledge.Clone(h.Graph).Nodes.Find(n=>n.Id==node.Id);Check(roundTrip.ReadingGuide.Terms[0].Term=="NPUWorker"&&roundTrip.ReadingGuide.Steps[0].Original==node.Summary,"original and separate guide survive archive serialization");
   string before=GraphEditing.Revision(h.Graph);guide.Steps[0].CodeUrl=RepositoryLearning.CodeLocations(node)[0];h.Api.Result=GraphEditing.Json(guide);h.Service.TranslateNodeTerms(h.Graph,saved,r=>result=r);h.Queue.Run();Check(!result.Success&&GraphEditing.Revision(h.Graph)==before,"an unread local source cannot be used as a verified code mapping");
   guide.Steps[0].CodeUrl="";guide.Steps[0].Original="模型编造的原文";h.Api.Result=GraphEditing.Json(guide);h.Service.TranslateNodeTerms(h.Graph,saved,r=>result=r);h.Queue.Run();Check(!result.Success&&GraphEditing.Revision(h.Graph)==before,"flow steps must quote actual original text");
   guide.Steps[0].Original=node.Summary;h.Api.Result=GraphEditing.Json(guide);h.Service.TranslateNodeTerms(h.Graph,saved,r=>result=r);h.Service.Slot.DomainGraphs[0].Nodes[0].Summary="并发编辑";h.Queue.Run();Check(!result.Success,"concurrent archive changes do not get overwritten by late translations");
   h.Api.Results.Enqueue("{\"Terms\":[{\"Term\":\"a\",\"Term\":\"b\",\"Meaning\":\"重复字段\"}],\"Steps\":[]}");h.Api.Results.Enqueue(GraphEditing.Json(guide));int calls=h.Api.Calls;h.Service.TranslateNodeTerms(h.Graph,h.Graph.Nodes.Find(n=>n.Id==node.Id),r=>result=r);h.Queue.Run();Check(result.Success&&h.Api.Calls==calls+3,"malformed structured output gets one bounded model repair rather than partial persistence");
   var prior=new DomainNode{Summary="通俗摘要",Approach="术语对照：\nasyncio：解释\nEngineCore：解释",ReadingGuide=translation};var required=NodeReadingGuide.RequiredTerms(prior);Check(required.Contains("asyncio")&&required.Contains("EngineCore")&&required.Contains("NPUWorker"),"retranslation preserves terms from earlier definitions even after a plain-language rewrite");
  }}
 }
}
